CREATE FUNCTION public.apply_order_loyalty() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE balance integer; BEGIN IF NEW.phone<>'' AND (NEW.points_earned>0 OR NEW.points_redeemed>0) THEN INSERT INTO public.loyalty_accounts(phone,points) VALUES(NEW.phone,0) ON CONFLICT DO NOTHING; SELECT points INTO balance FROM public.loyalty_accounts WHERE phone=NEW.phone FOR UPDATE; IF balance<NEW.points_redeemed THEN RAISE EXCEPTION 'Pontos insuficientes para o resgate'; END IF; UPDATE public.loyalty_accounts SET points=points-NEW.points_redeemed+NEW.points_earned,updated_at=now() WHERE phone=NEW.phone; END IF; RETURN NEW; END $$;
CREATE TRIGGER order_atomic_loyalty BEFORE INSERT ON public.orders FOR EACH ROW EXECUTE FUNCTION public.apply_order_loyalty();
CREATE FUNCTION public.requeue_print(_job uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; UPDATE public.print_jobs SET state='pending',device_id=NULL,claimed_at=NULL WHERE id=_job AND (state='failed' OR (state='printing' AND claimed_at<now()-interval '5 minutes')); RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.requeue_print(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.requeue_print(uuid) TO authenticated;
CREATE FUNCTION public.private_review_state(_order uuid,_token uuid) RETURNS TABLE(reviewed boolean,scheduled_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.order_reviews r WHERE r.order_id=o.id),o.scheduled_at FROM public.orders o WHERE o.id=_order AND o.review_token=_token $$;
REVOKE ALL ON FUNCTION public.private_review_state(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.private_review_state(uuid,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.insert_club_order(_order jsonb,_member uuid,_token uuid,_credits integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.club_members; result uuid; BEGIN SELECT * INTO m FROM public.club_members WHERE id=_member AND redemption_token=_token AND status='active' AND period_end>now() FOR UPDATE; IF NOT FOUND OR m.credits<_credits OR _credits<0 OR m.phone IS DISTINCT FROM _order->>'phone' OR (m.is_demo AND NOT (_order->>'is_demo')::boolean) OR NOT (SELECT club_enabled FROM public.store_settings WHERE id=1) THEN RAISE EXCEPTION 'Saldo do clube indisponível'; END IF; INSERT INTO public.orders(customer_name,phone,address,delivery_method,items,total,discount,is_demo,points_earned,points_redeemed,table_id,people,scheduled_at,delivery_fee,delivery_zone,club_member_id,club_credits_used,vip) VALUES(_order->>'customer_name',_order->>'phone',_order->>'address',_order->>'delivery_method',_order->'items',(_order->>'total')::numeric,(_order->>'discount')::numeric,(_order->>'is_demo')::boolean,(_order->>'points_earned')::integer,(_order->>'points_redeemed')::integer,(_order->>'table_id')::uuid,(_order->>'people')::integer,(_order->>'scheduled_at')::timestamptz,(_order->>'delivery_fee')::numeric,_order->>'delivery_zone',_member,_credits,(_order->>'vip')::boolean) RETURNING id INTO result; UPDATE public.club_members SET credits=credits-_credits WHERE id=m.id; RETURN result; END $$;